"""L2 -- the arithmetic every detector is made of.

No model here, and no images. Two boxes are two rectangles, and the question
"are these the same object?" is a number you can compute by hand. Every
detector in the course rests on this function, including the one you called in
L1 -- it is how a detector decides that fourteen overlapping guesses are one
stop sign.
"""

from __future__ import annotations

import numpy as np



def iou(box_a, box_b):
    """Intersection over union of two boxes.

    Each box is (x1, y1, x2, y2) with x1 < x2 and y1 < y2, in pixels.
    Returns a float in [0, 1]: the area they share, divided by the area they
    cover together. Boxes that do not touch return 0.0. Identical boxes
    return 1.0.

    Watch the case where the boxes do not overlap. The width or height of the
    intersection can come out negative, and a negative side length quietly
    produces an area.
    """
    ax1, ay1, ax2, ay2 = (float(v) for v in box_a)
    bx1, by1, bx2, by2 = (float(v) for v in box_b)
    iw = max(0.0, min(ax2, bx2) - max(ax1, bx1))
    ih = max(0.0, min(ay2, by2) - max(ay1, by1))
    inter = iw * ih
    union = (ax2 - ax1) * (ay2 - ay1) + (bx2 - bx1) * (by2 - by1) - inter
    if union <= 0.0:
        return 0.0
    return inter / union


def filter_detections(boxes, scores, labels, *, min_score, keep_labels=None):
    """Drop detections that are too weak or the wrong class.

    boxes   : (N, 4) float array
    scores  : (N,)   float array
    labels  : list of N strings
    Returns (boxes_kept, scores_kept, labels_kept) with the same types and the
    original order preserved. Keeping nothing returns empty arrays with shape
    (0, 4) and (0,) -- not None.

    `keep_labels` of None means every label passes.
    """
    boxes = np.asarray(boxes, dtype=float).reshape(-1, 4)
    scores = np.asarray(scores, dtype=float).reshape(-1)
    labels = list(labels)
    if not (len(boxes) == len(scores) == len(labels)):
        raise ValueError("boxes, scores and labels must have the same length")
    keep = scores >= min_score
    if keep_labels is not None:
        allowed = set(keep_labels)
        keep &= np.array([lbl in allowed for lbl in labels], dtype=bool)
    idx = np.flatnonzero(keep)
    return boxes[idx].reshape(-1, 4), scores[idx], [labels[i] for i in idx]


def non_max_suppression(boxes, scores, iou_threshold=0.5):
    """BONUS -- collapse overlapping boxes into one per object.

    Returns the indices of the boxes to keep, as an int array, highest score
    first. The rule: take the best remaining box, discard everything that
    overlaps it by more than `iou_threshold`, repeat.

    Graded on speed as well as correctness, against the grader's own
    implementation of the same algorithm, so a five-deep loop nest will pass
    correctness and lose the ratio.
    """
    boxes = np.asarray(boxes, dtype=float).reshape(-1, 4)
    scores = np.asarray(scores, dtype=float).reshape(-1)
    x1, y1, x2, y2 = boxes.T
    areas = (x2 - x1) * (y2 - y1)
    # Stable sort so equal scores keep input order, matching a sorted() reference.
    order = np.argsort(-scores, kind="stable")
    keep = []
    while order.size:
        i = order[0]
        keep.append(i)
        rest = order[1:]
        iw = np.clip(np.minimum(x2[i], x2[rest]) - np.maximum(x1[i], x1[rest]), 0.0, None)
        ih = np.clip(np.minimum(y2[i], y2[rest]) - np.maximum(y1[i], y1[rest]), 0.0, None)
        inter = iw * ih
        union = areas[i] + areas[rest] - inter
        overlap = np.divide(inter, union, out=np.zeros_like(inter), where=union > 0)
        order = rest[overlap <= iou_threshold]
    return np.asarray(keep, dtype=np.int64)
